--  Скрипт идемпотентен: удаляет только свои данные и вставляет заново.
-- ============================================================================
BEGIN;

-- ---------- очистка предыдущего прогона ----------
DELETE FROM "Attendances"    WHERE "TrainingId" IN (SELECT "Id" FROM "Trainings" WHERE "VenueId" IN (SELECT "Id" FROM "Venues" WHERE "Name" IN ('Стадион «Динамо»', 'Манеж «Олимпийский»', 'Поле «Академия»')));
DELETE FROM "Trainings"      WHERE "VenueId" IN (SELECT "Id" FROM "Venues" WHERE "Name" IN ('Стадион «Динамо»', 'Манеж «Олимпийский»', 'Поле «Академия»'));
DELETE FROM "Subscriptions"  WHERE "PlayerId" IN (SELECT "Id" FROM "Players" WHERE "ParentId" IN (SELECT "Id" FROM "Users" WHERE "Email" LIKE 'parent%@academy.local'));
DELETE FROM "Players"        WHERE "ParentId" IN (SELECT "Id" FROM "Users" WHERE "Email" LIKE 'parent%@academy.local');
DELETE FROM "ParentProfiles" WHERE "UserId"   IN (SELECT "Id" FROM "Users" WHERE "Email" LIKE 'parent%@academy.local');
DELETE FROM "Groups"         WHERE "CoachId"  IN (SELECT "Id" FROM "Coaches" WHERE "UserId" IN (SELECT "Id" FROM "Users" WHERE "Email" LIKE 'luish.figu@%' OR "Email" LIKE 'pep.gvardiola@%'));
DELETE FROM "Coaches"        WHERE "UserId"   IN (SELECT "Id" FROM "Users" WHERE "Email" LIKE 'luish.figu@%' OR "Email" LIKE 'pep.gvardiola@%');
DELETE FROM "UserRoles"      WHERE "UserId"   IN (SELECT "Id" FROM "Users" WHERE "Email" LIKE '%@academy.local');
DELETE FROM "Users"          WHERE "Email" LIKE '%@academy.local';
DELETE FROM "Venues"         WHERE "Name" IN ('Стадион «Динамо»', 'Манеж «Олимпийский»', 'Поле «Академия»');
DELETE FROM "TrainingPlans"  WHERE "Name" = 'Тестовый абонемент (16 занятий)';

-- ---------- роли должны существовать (их создаёт DbInitializer) ----------
DO $$
BEGIN
    IF (SELECT count(*) FROM "Roles" WHERE "NormalizedName" IN ('MANAGER','COACH','PARENT','PLAYER')) < 4 THEN
        RAISE EXCEPTION 'В таблице Roles нет всех ролей. Запустите приложение хотя бы раз (DbInitializer создаст роли), затем повторите скрипт.';
    END IF;
END $$;

